INSERT INTO public.maxims (
  id, latin_phrase, indonesian_meaning, literal_translation,
  pronunciation_guide, legal_fields, legal_meaning, history,
  is_active, status, difficulty, version_number, data,
  created_at, updated_at
) VALUES (
  'lex-specialis',
  'Lex Specialis Derogat Legi Generali',
  'Asas bahwa peraturan yang bersifat khusus mengesampingkan peraturan yang bersifat umum jika keduanya mengatur hal yang sama',
  'Undang-undang yang khusus menghapuskan undang-undang yang umum',
  '/lɛks spɛˈʃi.a.lɪs dɛˈro.ɡat ˈle.ɡi ɡɛnɛˈra.li/',
  ARRAY['tata-negara','pidana','administrasi'],
  'Lex Specialis Derogat Legi Generali adalah sebuah maksim hukum Latin yang berarti "undang-undang yang khusus mengesampingkan undang-undang yang umum." Asas ini berfungsi sebagai mekanisme penafsiran hukum untuk menentukan norma mana yang harus diterapkan ketika terdapat dua peraturan perundang-undangan yang setingkat, saling berkaitan, namun satu bersifat umum (general) dan lainnya bersifat khusus (special).

Fungsi utama dari asas ini adalah menjamin kepastian hukum dan keadilan substantif. Peraturan yang bersifat khusus biasanya dibuat dengan pertimbangan yang lebih mendalam terhadap objek tertentu, subjek tertentu, atau keadaan tertentu. Oleh karena itu, dianggap bahwa legislator memiliki niat yang lebih spesifik dan detail dalam peraturan khusus tersebut dibandingkan dalam peraturan umum yang mencakup cakupan luas. Dengan menerapkan asas Lex Specialis, sistem hukum memastikan bahwa aturan yang paling relevan dan tepat sasaranlah yang berlaku.

Ruang lingkup penerapan asas ini sering kali bersinggungan dengan asas Lex Posterior. Pertanyaan yang sering muncul adalah: apakah Undang-Undang Baru yang Umum mencabut Undang-Undang Lama yang Khusus? Atau sebaliknya? Dalam praktik hukum Indonesia, jawaban atas pertanyaan ini tidak selalu hitam-putih dan sangat bergantung pada niat legislator (legislative intent) yang dapat dilihat dari penjelasan umum, konsiderans, atau pasal-pasal transisi dalam undang-undang tersebut.',
  'Sejarah asas ini dapat ditelusuri melalui tahapan berikut:

Romawi Kuno: Prinsip "Specialia generalibus derogant" sudah dikenal dalam hukum Romawi. Para ahli hukum Romawi menyadari bahwa aturan umum (ius commune) tidak selalu cocok untuk kasus-kasus istimewa, sehingga diperlukan aturan khusus (ius speciale).

Corpus Juris Civilis (Abad ke-6 M): Justinianus I dalam Digesta dan Codex mencatat berbagai pendapat ahli hukum Romawi yang mendukung prioritas aturan khusus. Prinsip ini menjadi bagian dari warisan hukum tertulis Romawi.

Eropa Kontinental: Dalam perkembangan Ius Commune di Eropa, para glossator dan komentator memperkuat doktrin ini. Asas ini menjadi alat interpretasi standar dalam hukum kanonik dan hukum sipil Eropa.

Belanda: Sebagai negara penganut Civil Law, Belanda mengadopsi asas ini secara penuh dengan prinsip "de bijzondere wet gaat voor de algemene wet". Hal ini tercermin dalam praktik peradilan dan administrasi kolonial yang mempengaruhi Indonesia.

Indonesia (Pasca Kemerdekaan): Mahkamah Agung dan kemudian Mahkamah Konstitusi secara konsisten menggunakan asas ini dalam memutus sengketa norma. Asas ini diakui sebagai asas umum hukum yang berlaku dalam penyelesaian konflik norma sebagaimana dijelaskan dalam praktik aplikasi UU No. 12 Tahun 2011.',
  true,
  'stable',
  'menengah',
  1,
  '{"synonyms":["Asas kekhususan","Specialia generalibus derogant"],"usedIn":["Indonesia","Belanda","Jerman","Prancis","sebagian besar negara Civil Law"],"classification":{"legalBranch":"Hukum Tata Negara, Ilmu Perundang-Undangan, dan Hukum Pidana","nature":"Imperatif","applicationLevel":"Nasional dan Internasional","traditionSource":"Hukum Romawi Kuno, dikembangkan dalam Corpus Juris Civilis, dan diadopsi oleh doktrin hukum Eropa Kontinental"},"applicabilityStatus":{"validInIndonesia":true,"validInternationally":true,"recognizedByDoctrine":true,"codified":false,"notes":"Asas Umum (General Principle of Law) yang diakui dalam yurisprudensi dan doktrin. Tidak dikodifikasi dalam satu pasal tunggal."},"wordByWord":[{"word":"Lex","meaning":"Undang-undang, hukum, peraturan"},{"word":"Specialis","meaning":"Khusus, spesifik, istimewa"},{"word":"Derogat","meaning":"Mengurangi, membatalkan sebagian, mengesampingkan"},{"word":"Legi","meaning":"Kepada/Dari undang-undang"},{"word":"Generali","meaning":"Umum, umum berlaku, luas"}],"wordByWordExtended":[{"word":"Lex","latinForm":"Lex, Legis (f)","partOfSpeech":"Nomina","meaning":"Undang-undang, hukum, peraturan"},{"word":"Specialis","latinForm":"Specialis, -e","partOfSpeech":"Adjektiva","meaning":"Khusus, spesifik, istimewa"},{"word":"Derogat","latinForm":"Derogare (verba)","partOfSpeech":"Verba (Indikatif Aktif)","meaning":"Mengurangi, membatalkan sebagian, mengesampingkan"},{"word":"Legi","latinForm":"Lex, Legis (f)","partOfSpeech":"Nomina (Ablatif)","meaning":"Kepada/Dari undang-undang"},{"word":"Generali","latinForm":"Generalis, -e","partOfSpeech":"Adjektiva (Ablatif)","meaning":"Umum, umum berlaku, luas"}],"etymologyNotes":"Kalimat ini menggunakan struktur subjek-predikat-keterangan. Lex Specialis bertindak sebagai subjek (\"Undang-undang yang khusus\"). Derogat adalah predikat (\"mengesampingkan\"). Legi Generali berada dalam kasus Ablatif, yaitu \"dari undang-undang yang umum\". Secara harfiah, frasa ini menekankan prioritas substansi (kekhususan) di atas cakupan (keumuman).","philosophicalMeaning":{"origin":"Asas Lex Specialis muncul dari kebutuhan akan presisi dan keadilan dalam penerapan hukum. Legislator dianggap telah memberikan perhatian lebih besar dan rumusan yang lebih rinci ketika membuat aturan khusus.","justiceValue":"Hukum umum sering kali terlalu kaku atau terlalu luas untuk menangani situasi unik. Hukum khusus hadir untuk memberikan keadilan yang lebih pas (fitting justice) bagi subjek atau objek tertentu.","romanThought":"Prinsip \"Specialia generalibus derogant\" sudah dikenal dalam hukum Romawi. Para ahli hukum Romawi menyadari bahwa aturan umum (ius commune) tidak selalu cocok untuk kasus-kasus istimewa, sehingga diperlukan aturan khusus (ius speciale).","modernRelevance":"Relevansi modernnya terletak pada semakin banyaknya regulasi sektoral (seperti lingkungan hidup, perbankan, teknologi informasi) yang membutuhkan penanganan khusus di luar aturan umum administratif atau pidana."},"historyTimeline":[{"era":"Romawi Kuno","period":"Romawi Kuno","description":"Prinsip \"Specialia generalibus derogant\" sudah dikenal. Para ahli hukum menyadari bahwa aturan umum (ius commune) tidak selalu cocok untuk kasus istimewa."},{"era":"Corpus Juris Civilis","period":"Abad ke-6 M","description":"Justinianus I dalam Digesta dan Codex mencatat berbagai pendapat ahli hukum Romawi yang mendukung prioritas aturan khusus."},{"era":"Eropa Kontinental","period":"Abad Pertengahan","description":"Para glossator dan komentator memperkuat doktrin ini. Asas ini menjadi alat interpretasi standar dalam hukum kanonik dan hukum sipil Eropa."},{"era":"Belanda","period":"Masa Kolonial","description":"Belanda mengadopsi prinsip \"de bijzondere wet gaat voor de algemene wet\" secara penuh, mempengaruhi praktik peradilan di Indonesia."},{"era":"Indonesia","period":"Pasca Kemerdekaan","description":"MK secara konsisten menggunakan asas ini sebagai ratio decidendi. Diakui sebagai asas umum hukum dalam penyelesaian konflik norma."}],"doctrineDevelopment":[{"era":"Doktrin Klasik","description":"Awalnya diterapkan secara kaku. Jika ada aturan khusus, aturan umum otomatis tidak berlaku untuk kasus tersebut."},{"era":"Doktrin Legislative Intent","description":"Para ahli mulai menekankan pentingnya melihat niat legislator. Apakah aturan khusus dimaksud sebagai pengecualian permanen atau hanya pelengkap?"},{"era":"Doktrin Harmonisasi","description":"Doktrin modern berusaha menghindari pencabutan implisit. Hakim berupaya membaca aturan umum dan khusus secara harmonis (subsidiaritas)."},{"era":"Doktrin Konstitusionalisme","description":"Di era negara hukum konstitusional, baik aturan umum maupun khusus harus tunduk pada UUD 1945. Uji materiil ke MK menjadi mekanisme koreksi."}],"elements":["Adanya Dua Peraturan Perundang-Undangan: Harus ada minimal dua norma hukum tertulis.","Tingkatan Hierarki yang Sama: Kedua peraturan tersebut harus memiliki kedudukan yang setara dalam hierarki peraturan (misalnya: UU vs UU).","Hubungan Genus-Spesies: Harus ada hubungan logis di mana satu peraturan mencakup cakupan luas (genus/umum) dan lainnya mencakup cakupan sempit/spesifik (spesies/khusus).","Objek Materiil yang Tumpang Tindih: Kedua peraturan mengatur hal yang sama, namun aturan khusus mengaturnya dengan lebih detail atau berbeda.","Pertentangan atau Kelengkapan: Ada pertentangan langsung, atau aturan khusus dimaksudkan untuk melengkapi/mengecualikan aturan umum."],"conditions":["Kesetaraan Hierarki: Peraturan yang khusus dan umum harus berasal dari lembaga yang setara. Jika hierarki berbeda, berlaku Lex Superior Derogat Legi Inferiori.","Kekhususan yang Nyata: Peraturan yang diklaim \"khusus\" harus benar-benar mengatur aspek spesifik yang tidak diatur secara detail dalam peraturan umum. Mencegah klaim kekhususan yang palsu.","Tidak Ada Pencabutan Eksplisit: Peraturan umum yang baru tidak boleh secara eksplisit menyatakan mencabut peraturan khusus yang lama."],"exceptions":["Jika Peraturan Khusus Bertentangan dengan UUD 1945: Segala peraturan, apapun kekhususannya, yang bertentangan dengan UUD 1945 adalah batal demi hukum.","Jika Ada Klausul Pencabutan Eksplisit dalam UU Baru: Jika legislator menerbitkan UU Baru yang secara tegas mencabut peraturan khusus lama, maka UU Baru berlaku.","Jika Peraturan Khusus Sudah Kadaluarsa: Beberapa peraturan khusus dibuat untuk keadaan darurat atau sementara (temporary law). Jika masa berlakunya habis, aturan umum kembali berlaku.","Dalam Hukum Pidana (Prinsip Nullum Crimen): Jika aturan khusus tidak secara jelas mendefinisikan tindak pidana, hakim tidak boleh menggunakan analogi. Kekhususan dalam hukum pidana harus ditafsirkan secara ketat (strict interpretation)."],"scope":{"applies":["Konflik antar UU di mana satu UU bersifat sektoral/khusus (misal: UU Perbankan) dan UU lainnya bersifat umum (misal: KUHD atau UU Perseroan Terbatas).","Konflik antar Pasal dalam satu UU yang sama, di mana ada pasal umum dan pasal khusus.","Hubungan antara KUHP (hukum pidana umum) dengan UU Tindak Pidana Khusus (UU Narkotika, UU Tipikor, UU ITE)."],"doesNotApply":["Konflik antara UU dengan PP (berlaku Lex Superior).","Konflik antara UU dengan UUD 1945 (berlaku supremasi konstitusi).","Kasus di mana UU Baru secara eksplisit mencabut UU Lama Khusus."]},"legalBasisTable":[{"statute":"UU No. 12 Tahun 2011 (jo. UU No. 13/2022)","article":"Pasal 63","relevance":"Meskipun teks utamanya tentang hierarki dan waktu, penjelasan dan praktik hukum mengakui Lex Specialis sebagai asas penafsiran utama dalam konflik norma setingkat yang tidak terselesaikan oleh Lex Superior atau Lex Posterior."},{"statute":"KUHP","article":"Pasal 103 dsb.","relevance":"Banyak pasal dalam KUHP yang merujuk pada \"kecuali ditentukan lain dalam undang-undang khusus\". Ini adalah bentuk kodifikasi asas Lex Specialis dalam hukum pidana."},{"statute":"Putusan Mahkamah Konstitusi","article":"Berbagai Putusan","relevance":"MK secara konsisten menggunakan asas ini sebagai ratio decidendi dalam menguji konflik antar UU."}],"indonesianLegalBasis":"Diakui sebagai asas umum hukum dalam praktik yurisprudensi MK dan MA. Tercermin dalam ketentuan \"kecuali ditentukan lain\" di berbagai UU sektoral.","indonesianSystemRelation":"Bagi Hakim: menentukan pasal mana yang diterapkan — dalam kasus korupsi, UU Tipikor (khusus) didahulukan dari KUHP (umum). Bagi Legislator: memastikan UU Sektoral baru tidak bertentangan dengan UU Payung yang ada. Bagi Akademisi: menganalisis batas-batas kekhususan dan kapan aturan dianggap cukup \"khusus\".","normativeExamples":["Hukum Pidana: UU No. 31 Tahun 1999 jo. UU No. 20 Tahun 2001 tentang Pemberantasan Tindak Pidana Korupsi (UU Tipikor) merupakan Lex Specialis terhadap KUHP. Untuk tindak pidana korupsi, ketentuan UU Tipikor yang berlaku, bukan ketentuan penipuan atau penggelapan dalam KUHP.","Hukum Dagang/Bisnis: UU No. 40 Tahun 2007 tentang Perseroan Terbatas (UU PT) merupakan Lex Specialis terhadap KUHD untuk hal-hal yang diatur secara khusus. Jika UU PT diam, maka KUHD berlaku sebagai Lex Generalis.","Hukum Lingkungan: UU No. 32 Tahun 2009 tentang Perlindungan dan Pengelolaan Lingkungan Hidup merupakan Lex Specialis untuk isu lingkungan, yang dapat mengesampingkan ketentuan umum dalam perizinan berusaha jika ada konflik norma spesifik terkait AMDAL."],"practicalExamples":["Penanganan Kasus Korupsi: Jaksa Penuntut Umum mendakwa tersangka korupsi dengan pasal-pasal dalam UU Tipikor, bukan pasal penipuan dalam KUHP, karena UU Tipikor adalah aturan khusus dengan ancaman pidana lebih berat dan prosedur pembuktian terbalik.","Sengketa Perusahaan: Dalam sengketa internal perusahaan terbatas, pengacara merujuk pada UU Perseroan Terbatas terlebih dahulu. Hanya jika UU PT tidak mengaturnya, mereka merujuk pada KUHD atau KUHPerdata.","Perizinan Sektor Khusus: Pengusaha bidang perbankan mengikuti ketentuan OJK berdasarkan UU Perbankan (aturan khusus) daripada ketentuan umum perizinan usaha jika ada perbedaan prosedur."],"jurisprudence":[{"id":"mk-55-2010","courtName":"Mahkamah Konstitusi","caseNumber":"No. 55/PUU-VIII/2010","year":2010,"date":"2010","context":"Pengujian UU KPK vs UU Umum","excerpt":"MK menegaskan bahwa UU KPK adalah lex specialis dalam penegakan hukum tindak pidana korupsi.","summary":"Menegaskan prioritas UU Khusus (KPK) atas aturan umum dalam konteks penyelidikan dan penyidikan.","analysis":"Menegaskan bahwa UU KPK sebagai aturan khusus mengesampingkan prosedur umum KUHAP dalam konteks penyelidikan korupsi.","sourceUrl":"https://www.mkri.id"},{"id":"mk-12-2014","courtName":"Mahkamah Konstitusi","caseNumber":"No. 12/PUU-XII/2014","year":2014,"date":"2014","context":"Konflik Norma UU Minerba vs UU Pemda","excerpt":"MK menggunakan prinsip kekhususan untuk menentukan kewenangan pemerintah pusat vs daerah dalam pengelolaan mineral.","summary":"Menunjukkan bagaimana Lex Specialis digunakan untuk membagi kewenangan berdasarkan sifat objek (minerba).","analysis":"UU Minerba sebagai aturan khusus menentukan pembagian kewenangan pusat-daerah untuk sumber daya mineral, mengesampingkan UU Pemda yang bersifat umum.","sourceUrl":"https://www.mkri.id"},{"id":"ma-210-2015","courtName":"Mahkamah Agung","caseNumber":"No. 210/PID.SUS/2015/PN.Jkt.Pst","year":2015,"date":"2015","context":"Kasus Narkotika","excerpt":"Hakim menerapkan UU Narkotika (Khusus) daripada KUHP (Umum) untuk penentuan pidana.","summary":"Contoh penerapan Lex Specialis di tingkat Pengadilan Negeri dalam hukum pidana.","analysis":"Hakim konsisten menerapkan UU Narkotika sebagai aturan khusus untuk ancaman pidana narkotika, tidak menggunakan pasal KUHP yang lebih ringan.","sourceUrl":"https://www.mahkamahagung.go.id"}],"caseExamples":[],"internationalComparisons":[{"country":"Belanda","status":"Dikenal","description":"Asas ini dikenal dengan prinsip \"De bijzondere wet gaat voor de algemene wet\". Belanda sangat ketat dalam penerapannya, namun juga sangat menghargai keseimbangan dengan Lex Posterior."},{"country":"Jerman","status":"Dikenal","description":"Hukum Jerman mengenal prinsip \"Spezialität geht vor Generalität\". Doktrin Jerman sangat sistematis dalam membedakan antara Tatbestand (unsur perbuatan) yang khusus dan umum."},{"country":"Prancis","status":"Dikenal","description":"Prinsip \"La loi spéciale déroge à la loi générale\" berlaku. Prancis cenderung lebih kaku dalam penerapannya demi kepastian hukum administratif."},{"country":"Inggris","status":"Dikenal Sebagian","description":"Inggris tidak memiliki asas Lex Specialis yang formal. Namun dalam penafsiran statuta, pengadilan Inggris menerapkan prinsip \"Generalia specialibus non derogant\" (aturan umum tidak mencabut aturan khusus)."},{"country":"Amerika Serikat","status":"Dikenal Sebagian","description":"Prinsip \"Specific governs the general\" diakui dalam penafsiran statuta federal. Namun sering terjadi perdebatan kompleks antara hukum federal dan negara bagian."}],"maximComparisons":[{"maximId":"lex-superior","latinPhrase":"Lex Superior Derogat Legi Inferiori","whenUsed":"Digunakan ketika terjadi konflik antara peraturan yang berbeda tingkatan. Lebih kuat daripada Lex Specialis."},{"maximId":"lex-posterior","latinPhrase":"Lex Posterior Derogat Legi Priori","whenUsed":"Digunakan ketika terjadi konflik antara peraturan setingkat yang sama-sama umum/khusus. Seringkali menjadi pesaing Lex Specialis."},{"maximId":"lex-specialis","latinPhrase":"Lex Specialis Derogat Legi Generali","whenUsed":"Digunakan ketika terjadi konflik antara aturan umum dan aturan khusus, terlepas dari waktu (jika setingkat). Berlaku prioritas substansi."}],"analysis":{"purpose":"Menciptakan presisi hukum dan keadilan yang sesuai dengan karakteristik kasus tertentu.","protectedValues":"Keadilan substantif, efektivitas penegakan hukum, dan penghormatan terhadap niat legislator yang detail.","advantages":"Memungkinkan penanganan kasus yang kompleks dan spesifik dengan aturan yang dirancang khusus untuk itu.","critique":"Dapat menimbulkan fragmentasi hukum (legal fragmentation) di mana terlalu banyak aturan khusus membuat sistem hukum menjadi rumit dan sulit dipahami oleh masyarakat awam.","limitations":"Sulit menentukan batas antara \"umum\" dan \"khusus\". Terkadang sebuah aturan yang dianggap khusus oleh satu pihak, dianggap umum oleh pihak lain."},"scholarViews":[{"name":"Prof. Dr. Jimly Asshiddiqie, S.H., M.H.","view":"Asas Lex Specialis adalah alat penafsiran yang vital untuk menjaga koherensi sistem hukum. Aturan khusus harus dibaca sebagai pengecualian dari aturan umum, dan pengecualian harus ditafsirkan secara ketat (exceptiones sunt strictissimae interpretationis).","source":"Ilmu Perundang-Undangan: Studi Jenis dan Fungsi Peraturan Perundang-Undangan (2006)"},{"name":"Prof. Dr. Maria Farida Indrati, S.H., M.H.","view":"Penerapan Lex Specialis memerlukan analisis mendalam terhadap materi muatan peraturan. Kekhususan tidak hanya dilihat dari judul UU, tetapi dari substansi pasalnya.","source":"Ilmu Perundang-Undangan: Jenis, Fungsi, dan Materi Muatan (2007)"},{"name":"Dr. H. A. Hamid S. Attamimi","view":"Praktik perundang-undangan di Indonesia sering membuat UU Sektoral tanpa harmonisasi yang baik dengan UU Payung, sehingga menyebabkan konflik Lex Specialis yang berkepanjangan dan merugikan kepastian hukum.","source":"Peranan Keputusan Presiden Republik Indonesia dalam Penyelenggaraan Pemerintahan Negara (1990)"}],"controversies":[{"title":"Konflik antara UU Baru yang Umum dan UU Lama yang Khusus","description":"Ketika UU Cipta Kerja (bersifat omnibus/umum) diterbitkan, muncul perdebatan apakah ia mencabut UU Sektoral lama yang khusus. Sebagian ahli berpendapat UU Cipta Kerja adalah Lex Posterior yang mencabut, sementara ahli lain berpendapat UU Sektoral Lama adalah Lex Specialis yang tetap berlaku kecuali diubah secara eksplisit. Ketidakjelasan niat legislator dalam konsiderans sering menjadi sumber sengketa ini."}],"commonMistakes":[{"misconception":"\"Aturan khusus selalu menang.\"","fact":"Tidak selalu. Jika aturan khusus bertentangan dengan aturan umum yang lebih tinggi hierarkinya (Lex Superior), aturan umum yang lebih tinggi yang menang."},{"misconception":"\"Lex Specialis hanya untuk hukum pidana.\"","fact":"Salah. Asas ini berlaku di semua cabang hukum, termasuk perdata, tata negara, dan administrasi."},{"misconception":"\"Jika UU Baru terbit, UU Lama Khusus otomatis gugur.\"","fact":"Belum tentu. Jika UU Baru bersifat umum dan tidak mencabut secara eksplisit, UU Lama Khusus sering kali tetap berlaku sebagai pengecualian."}],"faq":[{"question":"Apakah Lex Specialis berlaku untuk Peraturan Daerah?","answer":"Ya, jika ada Perda Khusus (misal: Perda Pajak Daerah) dan Perda Umum, aturan khusus pajak akan berlaku untuk urusan pajak."},{"question":"Bagaimana jika dua UU sama-sama mengklaim sebagai khusus?","answer":"Maka akan dilihat hierarkinya (jika beda), atau waktunya (Lex Posterior), atau dicari harmonisasi oleh hakim/MK."},{"question":"Apakah KUHP masih berlaku jika ada UU Tindak Pidana Khusus?","answer":"KUHP tetap berlaku sebagai Lex Generalis. UU Khusus hanya berlaku untuk unsur-unsur yang diatur secara spesifik. Untuk unsur yang tidak diatur di UU Khusus, KUHP bisa berlaku subsidiar."},{"question":"Siapa yang menentukan apakah suatu aturan itu khusus atau umum?","answer":"Pada awalnya pembentuk undang-undang, namun dalam sengketa, Hakim atau Mahkamah Konstitusi yang menentukannya melalui penafsiran."},{"question":"Apakah Lex Specialis bisa dibatalkan?","answer":"Aturan khusus bisa dicabut oleh legislator melalui UU baru yang secara eksplisit mencabutnya, atau dibatalkan oleh MK jika inkonstitusional."}],"maximNotes":"Penting untuk membaca Penjelasan Umum dan Konsiderans sebuah UU untuk mengetahui apakah legislator bermaksud menjadikannya sebagai Lex Specialis atau Lex Generalis. Dalam praktik, sering terjadi tumpang tindih kewenangan antar lembaga karena masing-masing merasa memiliki aturan khusus (sectoral ego).","relatedTerms":[{"term":"Subsidiaritas","definition":"Aturan umum berlaku jika aturan khusus tidak mengatur."},{"term":"Strict Interpretation","definition":"Penafsiran ketat untuk aturan khusus/pidana."},{"term":"Exceptiones sunt strictissimae interpretationis","definition":"Pengecualian harus ditafsirkan secara ketat."},{"term":"Harmonisasi Peraturan","definition":"Upaya menyesuaikan berbagai peraturan agar tidak saling bertentangan."},{"term":"Konflik Norma","definition":"Situasi di mana dua atau lebih norma hukum bertentangan satu sama lain."},{"term":"Legislative Intent","definition":"Niat Pembuat Undang-Undang — tujuan yang ingin dicapai saat membuat peraturan."},{"term":"Omnibus Law","definition":"Metode pembentukan UU yang menggabungkan banyak sektor dalam satu UU sekaligus."},{"term":"Lex Generalis","definition":"Hukum Umum — peraturan yang berlaku secara luas untuk semua kasus."},{"term":"Lex Specialis","definition":"Hukum Khusus — peraturan yang berlaku secara spesifik untuk kasus tertentu."},{"term":"Judicial Review","definition":"Uji Materiil — mekanisme pengujian peraturan terhadap UUD oleh MK."}],"relations":[{"id":"lex-superior","latinPhrase":"Lex Superior Derogat Legi Inferiori","indonesianMeaning":"Hukum yang lebih tinggi mengesampingkan hukum yang lebih rendah","relationType":"hierarkis"},{"id":"lex-posterior","latinPhrase":"Lex Posterior Derogat Legi Priori","indonesianMeaning":"Hukum baru mengesampingkan hukum lama","relationType":"terkait"}],"references":{"primary":{"constitutions":["Undang-Undang Dasar Negara Republik Indonesia Tahun 1945."],"statutes":["Undang-Undang Nomor 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-Undangan.","Undang-Undang Nomor 31 Tahun 1999 jo. UU No. 20 Tahun 2001 tentang Pemberantasan Tindak Pidana Korupsi.","Undang-Undang Nomor 40 Tahun 2007 tentang Perseroan Terbatas.","Kitab Undang-Undang Hukum Pidana (KUHP), khususnya Pasal 103."],"rulings":["Putusan Mahkamah Konstitusi No. 55/PUU-VIII/2010.","Putusan Mahkamah Konstitusi No. 12/PUU-XII/2014."]},"secondary":{"books":["Asshiddiqie, Jimly. (2006). Ilmu Perundang-Undangan: Studi Jenis dan Fungsi Peraturan Perundang-Undangan. Yogyakarta: PT Kanisius.","Indrati, Maria Farida. (2007). Ilmu Perundang-Undangan: Jenis, Fungsi, dan Materi Muatan. Yogyakarta: Kanisius.","Attamimi, Hamid S. (1990). Peranan Keputusan Presiden Republik Indonesia dalam Penyelenggaraan Pemerintahan Negara. Disertasi Doktor, Universitas Indonesia.","Rahardjo, Satjipto. Biarkan Hukum Mengalir.","Rasjidi, Lili. Dasar-Dasar Filsafat dan Teori Hukum."],"journals":["Jurnal Hukum IUS QUIA IUSTUM. Artikel mengenai konflik norma dan Lex Specialis.","Jurnal Konstitusi (Mahkamah Konstitusi)."]},"tertiary":{"encyclopedias":["Badan Pembinaan Hukum Nasional (BPHN). Hierarki Peraturan Perundang-Undangan.","Direktori Putusan Mahkamah Konstitusi RI."]}},"furtherReading":[{"title":"Biarkan Hukum Mengalir","author":"Satjipto Rahardjo","type":"buku"},{"title":"Dasar-Dasar Filsafat dan Teori Hukum","author":"Lili Rasjidi","type":"buku"},{"title":"Jurnal Hukum IUS QUIA IUSTUM","author":"Berbagai Penulis","type":"jurnal"},{"title":"Jurnal Konstitusi","author":"Mahkamah Konstitusi","type":"jurnal"}],"meta":{"categories":["Asas Hukum","Teori Perundang-Undangan"],"portals":["Hukum Tata Negara","Ilmu Hukum","Hukum Pidana"],"tags":["Lex Specialis","Konflik Norma","Hukum Khusus","Hukum Umum","UU Tipikor","KUHP","Mahkamah Konstitusi"]}}'::jsonb,
